<?php

declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';

use EventMenu\Core\Database;
use EventMenu\Core\Security;
use EventMenu\Services\CatalogOptionsService;
use EventMenu\Services\OrderSchedulingService;
use EventMenu\Services\OnlineOrderingService;
use EventMenu\Services\PublicOrderService;

$pdo=Database::connection();
$slug=trim((string)($_GET['empresa']??''));
$stmt=$pdo->prepare('SELECT * FROM tenants WHERE slug=? AND status="active" LIMIT 1');
$stmt->execute([$slug]);
$tenant=$stmt->fetch();
if(!$tenant){http_response_code(404);exit('Empresa não encontrada.');}
$tenantId=(int)$tenant['id'];
try{$m=$pdo->prepare('SELECT enabled FROM tenant_modules WHERE tenant_id=? AND module_key="menu" LIMIT 1');$m->execute([$tenantId]);$enabled=$m->fetchColumn();if($enabled!==false&&!(bool)$enabled){http_response_code(404);exit('Cardápio indisponível.');}}catch(Throwable){}

$settings=json_decode((string)($tenant['settings']??'{}'),true);if(!is_array($settings))$settings=[];
$primary=preg_match('/^#[0-9a-fA-F]{6}$/',(string)($tenant['primary_color']??''))?(string)$tenant['primary_color']:'#6d4aff';
$secondary=preg_match('/^#[0-9a-fA-F]{6}$/',(string)($tenant['secondary_color']??''))?(string)$tenant['secondary_color']:'#8b5cf6';
$background=preg_match('/^#[0-9a-fA-F]{6}$/',(string)($settings['menu_background_color']??''))?(string)$settings['menu_background_color']:'#f6f5fa';
$headline=trim((string)($settings['menu_headline']??''))?:$tenant['name'];
$subtitle=trim((string)($settings['menu_subtitle']??''))?:'Peça online com rapidez e segurança';
$logo=(string)($settings['menu_logo_url']??'');$banner=(string)($settings['menu_banner_url']??'');
$showImages=(bool)($settings['menu_show_images']??true);$showDescriptions=(bool)($settings['menu_show_descriptions']??true);$showPreparation=(bool)($settings['menu_show_preparation']??true);$showBadges=(bool)($settings['menu_show_badges']??true);$showFeatured=(bool)($settings['menu_show_featured']??true);$showBrand=(bool)($settings['menu_show_eventmenu_brand']??true);$searchEnabled=(bool)($settings['menu_search_enabled']??true);$categoryStyle=(string)($settings['menu_category_style']??'chips');$layout=(string)($settings['menu_layout']??'cards');$cartTitle=trim((string)($settings['menu_cart_title']??'Meu pedido'))?:'Meu pedido';$addLabel=trim((string)($settings['menu_add_button_label']??'Adicionar'))?:'Adicionar';

$units=[];try{$u=$pdo->prepare('SELECT id,name,slug,address,city,phone FROM business_units WHERE tenant_id=? AND status="active" ORDER BY name');$u->execute([$tenantId]);$units=$u->fetchAll();}catch(Throwable){}
$unitParam=trim((string)($_GET['unidade']??''));$unit=null;
if($unitParam!==''&&$units){foreach($units as$u){if((string)$u['slug']===$unitParam||(string)$u['id']===$unitParam){$unit=$u;break;}}if(!$unit){http_response_code(404);exit('Unidade não encontrada.');}}
elseif(count($units)===1)$unit=$units[0];
$unitId=$unit?(int)$unit['id']:null;

$ordering=new OnlineOrderingService();
$deliveryStatus=$ordering->statusAt($pdo,$tenantId,'delivery');
$pickupEnabled=(bool)($settings['pickup_enabled']??true);
$pickupStatus=$pickupEnabled?$ordering->statusAt($pdo,$tenantId,'pickup'):['open'=>false,'reason'=>'Retirada indisponível.'];
$schedulingEnabled=(bool)($settings['scheduling_enabled']??false);$scheduler=new OrderSchedulingService();$deliverySlots=$schedulingEnabled?$scheduler->availableSlots($pdo,$tenantId,'delivery',50):[];$pickupSlots=$schedulingEnabled&&$pickupEnabled?$scheduler->availableSlots($pdo,$tenantId,'pickup',50):[];

$cartKey='menu:'.$tenantId.':'.($unitId??0);if(!isset($_SESSION['public_carts'][$cartKey])||!is_array($_SESSION['public_carts'][$cartKey]))$_SESSION['public_carts'][$cartKey]=[];$cart=&$_SESSION['public_carts'][$cartKey];$error=null;
$menuUrl=function(string$fragment='')use($slug,$unit):string{$q=['empresa'=>$slug];if($unit)$q['unidade']=$unit['slug'];return app_url('/menu.php?'.http_build_query($q).$fragment);};

if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!Security::validateCsrf($_POST['_csrf']??null))$error='Sessão expirada. Atualize a página.';
    else try{
        $action=(string)($_POST['action']??'');
        if($action==='add'){
            $id=(int)($_POST['product_id']??0);$qty=max(1,min(50,(int)($_POST['qty']??1)));$optionIds=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['option_ids']??[])),fn($v)=>$v>0)));sort($optionIds);
            $p=$pdo->prepare('SELECT id,unit_id FROM products WHERE id=? AND tenant_id=? AND active=1');$p->execute([$id,$tenantId]);$product=$p->fetch();if(!$product||($unitId&&$product['unit_id']!==null&&(int)$product['unit_id']!==$unitId))throw new RuntimeException('Produto indisponível nesta unidade.');
            (new CatalogOptionsService())->validateSelection($pdo,$tenantId,$id,$optionIds);$key=hash('sha256',$id.'|'.implode(',',$optionIds));if(isset($cart[$key]))$cart[$key]['qty']=min(50,(int)$cart[$key]['qty']+$qty);else$cart[$key]=['product_id'=>$id,'qty'=>$qty,'option_ids'=>$optionIds];header('Location: '.$menuUrl('#produtos'),true,303);exit;
        }
        if($action==='qty'){$key=(string)($_POST['line_key']??'');$qty=max(0,min(50,(int)($_POST['qty']??0)));if(isset($cart[$key])){if($qty===0)unset($cart[$key]);else$cart[$key]['qty']=$qty;}header('Location: '.$menuUrl('#carrinho'),true,303);exit;}
        if($action==='remove'){$key=(string)($_POST['line_key']??'');unset($cart[$key]);header('Location: '.$menuUrl('#carrinho'),true,303);exit;}
        if($action==='clear'){$cart=[];header('Location: '.$menuUrl(),true,303);exit;}
        if($action==='checkout'){
            $payload=array_values($cart);$buyer=['name'=>(string)($_POST['name']??''),'phone'=>(string)($_POST['phone']??''),'email'=>(string)($_POST['email']??''),'postal_code'=>(string)($_POST['postal_code']??''),'neighborhood'=>(string)($_POST['neighborhood']??''),'city'=>(string)($_POST['city']??''),'unit_id'=>$unitId];$mode=(string)($_POST['fulfillment']??'delivery');$scheduled=trim((string)($_POST['scheduled_for']??''));$service=new PublicOrderService();
            if($mode==='pickup')$result=$service->createPickup($tenantId,$payload,$buyer,(string)($_POST['coupon']??''),$scheduled!==''?$scheduled:null);elseif($mode==='delivery')$result=$service->createDelivery($tenantId,$payload,$buyer,(string)($_POST['address']??''),(string)($_POST['coupon']??''),$scheduled!==''?$scheduled:null);else throw new RuntimeException('Forma de recebimento inválida.');
            $cart=[];header('Location: '.app_url('/pedido.php?t='.urlencode($result['public_token'])),true,303);exit;
        }
    }catch(Throwable$e){$error=$e->getMessage();}
}

$where='tenant_id=? AND active=1';$args=[$tenantId];if($unitId){$where.=' AND (unit_id IS NULL OR unit_id=?)';$args[]=$unitId;}
$c=$pdo->prepare('SELECT * FROM categories WHERE '.$where.' ORDER BY sort_order,name');$c->execute($args);$categories=$c->fetchAll();
$p=$pdo->prepare('SELECT * FROM products WHERE '.$where.' ORDER BY featured DESC,category_id,name');$p->execute($args);$products=$p->fetchAll();$byId=[];foreach($products as$product)$byId[(int)$product['id']]=$product;

$groups=[];$options=[];$productIds=array_keys($byId);if($productIds){$marks=implode(',',array_fill(0,count($productIds),'?'));$g=$pdo->prepare('SELECT * FROM product_option_groups WHERE tenant_id=? AND active=1 AND product_id IN ('.$marks.') ORDER BY product_id,sort_order,id');$g->execute([$tenantId,...$productIds]);foreach($g->fetchAll()as$row)$groups[(int)$row['product_id']][]=$row;$groupIds=[];foreach($groups as$rows)foreach($rows as$row)$groupIds[]=(int)$row['id'];if($groupIds){$marks=implode(',',array_fill(0,count($groupIds),'?'));$o=$pdo->prepare('SELECT * FROM product_options WHERE active=1 AND group_id IN ('.$marks.') ORDER BY group_id,sort_order,id');$o->execute($groupIds);foreach($o->fetchAll()as$row)$options[(int)$row['group_id']][]=$row;}}

$catalog=new CatalogOptionsService();$cartLines=[];$cartTotal=0;$cartCount=0;foreach($cart as$key=>$row){$id=(int)($row['product_id']??0);if(!isset($byId[$id]))continue;$product=$byId[$id];try{$sel=$catalog->validateSelection($pdo,$tenantId,$id,(array)($row['option_ids']??[]));}catch(Throwable){continue;}$base=$product['promo_price_cents']!==null?(int)$product['promo_price_cents']:(int)$product['price_cents'];$unitPrice=max(0,$base+(int)$sel['delta_cents']);$qty=(int)$row['qty'];$line=$unitPrice*$qty;$cartTotal+=$line;$cartCount+=$qty;$cartLines[]=['key'=>$key,'product'=>$product,'qty'=>$qty,'options'=>$sel['options'],'unit_price'=>$unitPrice,'total'=>$line];}
function legacy_menu_money(int$c):string{return'R$ '.number_format($c/100,2,',','.');}
function legacy_menu_price(array$p):int{return$p['promo_price_cents']!==null?(int)$p['promo_price_cents']:(int)$p['price_cents'];}
$featured=array_values(array_filter($products,fn($p)=>!empty($p['featured'])));
