height:100%;aspect-ratio:auto}@media(max-width:850px){.featured-grid,.product-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.menu-layout-compact .product-grid{grid-template-columns:1fr}.legacy-hero{min-height:280px}.legacy-hero-inner{padding:45px 18px}.mobile-cart{display:block}.menu-cart-button{padding:9px 11px}.menu-brand-mini span{max-width:150px}}@media(max-width:560px){.featured-grid,.product-grid{grid-template-columns:1fr 1fr;gap:9px}.menu-content{padding-left:10px;padding-right:10px}.menu-product{border-radius:14px}.menu-product-body{padding:11px}.menu-product h3{font-size:14px}.menu-product-desc{font-size:10px;min-height:28px}.menu-price{font-size:15px}.menu-layout-classic .menu-product,.menu-layout-compact .menu-product{display:flex}.menu-layout-classic .menu-product-image,.menu-layout-compact .menu-product-image{height:auto;aspect-ratio:16/10}.legacy-hero h1{font-size:38px}.legacy-hero p{font-size:13px}.legacy-hero-logo{width:68px;height:68px}.category-wrap{top:68px}.checkout-form{grid-template-columns:1fr}.checkout-form .full,.checkout-submit{grid-column:1}.fulfillment-choices{grid-template-columns:1fr 1fr}}
