<?php foreach($categories as$cat):$catProducts=array_values(array_filter($products,fn($p)=>(int)$p['category_id']===(int)$cat['id']));if(!$catProducts)continue;?><section class="menu-section" id="cat-<?= (int)$cat['id'] ?>"><div class="menu-section-head"><div><h2><?= Security::e($cat['name']) ?></h2></div></div><div class="product-grid"><?php foreach($catProducts as$product):include __DIR__.'/partials/menu_product_legacy.php';endforeach;?></div></section><?php endforeach;?>
<?php if(!$products):?><div class="empty-menu"><h2>Cardápio em preparação</h2><p>Nenhum produto está disponível neste momento.</p></div><?php endif;?></main>
<div class="cart-overlay" data-close-cart></div><aside class="legacy-cart-drawer" id="carrinho"><div class="cart-head"><h2><?= Security::e($cartTitle) ?></h2><button class="cart-close" type="button" data-close-cart>×</button></div><div class="cart-body"><?php if(!$cartLines):?><div class="empty-menu"><strong>Seu carrinho está vazio.</strong><p>Adicione produtos para começar.</p></div><?php else:?><?php foreach($cartLines as$line):?><div class="cart-line"><div class="cart-line-top"><strong><?= Security::e($line['product']['name']) ?></strong><strong><?= legacy_menu_money($line['total']) ?></strong></div><?php if($line['options']):?><div class="cart-line-options"><?= Security::e(implode(' · ',array_column($line['options'],'name'))) ?></div><?php endif;?><div class="cart-line-actions"><form method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="qty"><input type="hidden" name="line_key" value="<?= Security::e($line['key']) ?>"><input type="number" name="qty" min="0" max="50" value="<?= (int)$line['qty'] ?>"><button class="secondary">Atualizar</button></form><form method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="line_key" value="<?= Security::e($line['key']) ?>"><button class="danger">Remover</button></form></div></div><?php endforeach;?><?php endif;?></div><?php if($cartLines):?><div class="cart-summary"><div class="cart-total"><span>Total</span><span><?= legacy_menu_money($cartTotal) ?></span></div><div class="checkout-stepper"><span><b>1</b>Pedido</span><span><b>2</b>Entrega</span><span><b>3</b>Pagamento</span></div><form method="post" class="checkout-form" id="legacyCheckout"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="checkout"><div class="full fulfillment-choices"><label class="fulfillment-choice"><input type="radio" name="fulfillment" value="delivery" checked> Delivery<br><small><?= Security::e($deliveryStatus['open']?'Disponível':(string)$deliveryStatus['reason']) ?></small></label><?php if($pickupEnabled):?><label class="fulfillment-choice"><input type="radio" name="fulfillment" value="pickup"> Retirada<br><small><?= Security::e($pickupStatus['open']?'Disponível':(string)$pickupStatus['reason']) ?></small></label><?php endif;?></div><label class="full">Quando?<select name="scheduled_for" id="legacySchedule" data-delivery='<?= Security::e(json_encode($deliverySlots,JSON_UNESCAPED_UNICODE|JSON_HEX_APOS|JSON_HEX_QUOT)) ?>' data-pickup='<?= Security::e(json_encode($pickupSlots,JSON_UNESCAPED_UNICODE|JSON_HEX_APOS|JSON_HEX_QUOT)) ?>'><option value="">O mais rápido possível</option></select></label><label>Nome<input name="name" required autocomplete="name"></label><label>Telefone<input name="phone" required autocomplete="tel"></label><label class="full">E-mail<input type="email" name="email" autocomplete="email"></label><div class="full" id="legacyDeliveryFields"><div class="checkout-form"><label>CEP<input name="postal_code" autocomplete="postal-code"></label><label>Bairro<input name="neighborhood"></label><label class="full">Cidade<input name="city"></label><label class="full">Endereço completo<textarea name="address"></textarea></label></div></div><label class="full">Cupom<input name="coupon" placeholder="Opcional"></label><button class="checkout-submit">Continuar para pagamento</button></form></div><?php endif;?></aside><?php if($cartCount):?><button class="mobile-cart" type="button" data-open-cart>Ver pedido · <?= legacy_menu_money($cartTotal) ?></button><?php endif;?>
<script>(function(){const body=document.body;document.querySelectorAll('[data-open-cart]').forEach(b=>b.addEventListener('click',()=>body.classList.add('cart-open')));document.querySelectorAll('[data-close-cart]').forEach(b=>b.addEventListener('click',()=>body.classList.remove('cart-open')));const search=document.getElementById('menuSearch');if(search)search.addEventListener('input',()=>{const q=search.value.trim().toLowerCase();document.querySelectorAll('.menu-product').forEach(card=>card.classList.toggle('hidden-search',q!==''&&!card.dataset.search.includes(q)));});const form=document.getElementById('legacyCheckout'),delivery=document.getElementById('legacyDeliveryFields'),schedule=document.getElementById('legacySchedule');if(form&&schedule){const parse=v=>{try{return JSON.parse(v||'[]')}catch(e){return[]}};const render=()=>{const mode=form.querySelector('input[name="fulfillment"]:checked')?.value||'delivery';if(delivery)delivery.style.display=mode==='delivery'?'block':'none';schedule.innerHTML='<option value="">O mais rápido possível</option>'+parse(schedule.dataset[mode]).map(s=>'<option value="'+String(s.value).replace(/"/g,'&quot;')+'">'+String(s.label)+'</option>').join('');};form.querySelectorAll('input[name="fulfillment"]').forEach(x=>x.addEventListener('change',render));render();}if(location.hash==='#carrinho')body.classList.add('cart-open');})();if('serviceWorker'in navigator)navigator.serviceWorker.register('<?= Security::e(app_url('/sw.js')) ?>').catch(()=>{});</script></body></html>
